39	export class TrimWhitespaceParticipant implements ITextFileSaveParticipant {
40	
41		constructor(
42			@IConfigurationService private readonly configurationService: IConfigurationService,
43			@ICodeEditorService private readonly codeEditorService: ICodeEditorService
44		) {
45			// Nothing
46		}
47	
48		async participate(model: ITextFileEditorModel, context: ITextFileSaveParticipantContext): Promise<void> {
49			if (!model.textEditorModel) {
50				return;
51			}
52	
53			const trimTrailingWhitespaceOption = this.configurationService.getValue<boolean>('files.trimTrailingWhitespace', { overrideIdentifier: model.textEditorModel.getLanguageId(), resource: model.resource });
54			const trimInRegexAndStrings = this.configurationService.getValue<boolean>('files.trimTrailingWhitespaceInRegexAndStrings', { overrideIdentifier: model.textEditorModel.getLanguageId(), resource: model.resource });
55			if (trimTrailingWhitespaceOption) {
56				this.doTrimTrailingWhitespace(model.textEditorModel, context.reason === SaveReason.AUTO, trimInRegexAndStrings);
57			}
58		}
59	
60		private doTrimTrailingWhitespace(model: ITextModel, isAutoSaved: boolean, trimInRegexesAndStrings: boolean): void {
61			let prevSelection: Selection[] = [];
62			let cursors: Position[] = [];
63	
64			const editor = findEditor(model, this.codeEditorService);
65			if (editor) {
66				// Find `prevSelection` in any case do ensure a good undo stack when pushing the edit
67				// Collect active cursors in `cursors` only if `isAutoSaved` to avoid having the cursors jump
68				prevSelection = editor.getSelections();
69				if (isAutoSaved) {
70					cursors = prevSelection.map(s => s.getPosition());
71					const snippetsRange = SnippetController2.get(editor)?.getSessionEnclosingRange();
72					if (snippetsRange) {
73						for (let lineNumber = snippetsRange.startLineNumber; lineNumber <= snippetsRange.endLineNumber; lineNumber++) {
74							cursors.push(new Position(lineNumber, model.getLineMaxColumn(lineNumber)));
75						}
76					}
77				}
78			}
79	
80			const ops = trimTrailingWhitespace(model, cursors, trimInRegexesAndStrings);
81			if (!ops.length) {
82				return; // Nothing to do
83			}
84	
85			model.pushEditOperations(prevSelection, ops, (_edits) => prevSelection);
86		}
87	}
88	
89	function findEditor(model: ITextModel, codeEditorService: ICodeEditorService): IActiveCodeEditor | null {
90		let candidate: IActiveCodeEditor | null = null;
91	
92		if (model.isAttachedToEditor()) {
93			for (const editor of codeEditorService.listCodeEditors()) {
94				if (editor.hasModel() && editor.getModel() === model) {
95					if (editor.hasTextFocus()) {
96						return editor; // favour focused editor if there are multiple
97					}
98	
99					candidate = editor;
100				}
101			}
102		}
103	
104		return candidate;
105	}
106	
107	export class FinalNewLineParticipant implements ITextFileSaveParticipant {
108	
109		constructor(
110			@IConfigurationService private readonly configurationService: IConfigurationService,
111			@ICodeEditorService private readonly codeEditorService: ICodeEditorService
112		) {
113			// Nothing
114		}
115	
116		async participate(model: ITextFileEditorModel, context: ITextFileSaveParticipantContext): Promise<void> {
117			if (!model.textEditorModel) {
118				return;
119			}
120	
121			if (this.configurationService.getValue('files.insertFinalNewline', { overrideIdentifier: model.textEditorModel.getLanguageId(), resource: model.resource })) {
122				this.doInsertFinalNewLine(model.textEditorModel);
123			}
124		}
125	
126		private doInsertFinalNewLine(model: ITextModel): void {
127			const lineCount = model.getLineCount();
128			const lastLine = model.getLineContent(lineCount);
129			const lastLineIsEmptyOrWhitespace = strings.lastNonWhitespaceIndex(lastLine) === -1;
130	
131			if (!lineCount || lastLineIsEmptyOrWhitespace) {
132				return;
133			}
134	
135			const edits = [EditOperation.insert(new Position(lineCount, model.getLineMaxColumn(lineCount)), model.getEOL())];
136			const editor = findEditor(model, this.codeEditorService);
137			if (editor) {
138				editor.executeEdits('insertFinalNewLine', edits, editor.getSelections());
139			} else {
140				model.pushEditOperations([], edits, () => null);
141			}
142		}
143	}
144	
145	export class TrimFinalNewLinesParticipant implements ITextFileSaveParticipant {
146	
147		constructor(
148			@IConfigurationService private readonly configurationService: IConfigurationService,
149			@ICodeEditorService private readonly codeEditorService: ICodeEditorService
150		) {
151			// Nothing
152		}
153	
154		async participate(model: ITextFileEditorModel, context: ITextFileSaveParticipantContext): Promise<void> {
155			if (!model.textEditorModel) {
156				return;
157			}
158	
159			if (this.configurationService.getValue('files.trimFinalNewlines', { overrideIdentifier: model.textEditorModel.getLanguageId(), resource: model.resource })) {
160				this.doTrimFinalNewLines(model.textEditorModel, context.reason === SaveReason.AUTO);
161			}
162		}
163	
164		/**
165		 * returns 0 if the entire file is empty
166		 */
167		private findLastNonEmptyLine(model: ITextModel): number {
168			for (let lineNumber = model.getLineCount(); lineNumber >= 1; lineNumber--) {
169				const lineLength = model.getLineLength(lineNumber);
170				if (lineLength > 0) {
171					// this line has content
172					return lineNumber;
173				}
174			}
175			// no line has content
176			return 0;
177		}
178	
179		private doTrimFinalNewLines(model: ITextModel, isAutoSaved: boolean): void {
180			const lineCount = model.getLineCount();
181	
182			// Do not insert new line if file does not end with new line
183			if (lineCount === 1) {
184				return;
185			}
186	
187			let prevSelection: Selection[] = [];
188			let cannotTouchLineNumber = 0;
189			const editor = findEditor(model, this.codeEditorService);
190			if (editor) {
191				prevSelection = editor.getSelections();
192				if (isAutoSaved) {
193					for (let i = 0, len = prevSelection.length; i < len; i++) {
194						const positionLineNumber = prevSelection[i].positionLineNumber;
195						if (positionLineNumber > cannotTouchLineNumber) {
196							cannotTouchLineNumber = positionLineNumber;
197						}
198					}
199				}
200			}
201	
202			const lastNonEmptyLine = this.findLastNonEmptyLine(model);
203			const deleteFromLineNumber = Math.max(lastNonEmptyLine + 1, cannotTouchLineNumber + 1);
204			const deletionRange = model.validateRange(new Range(deleteFromLineNumber, 1, lineCount, model.getLineMaxColumn(lineCount)));
205	
206			if (deletionRange.isEmpty()) {
207				return;
208			}
209	
210			model.pushEditOperations(prevSelection, [EditOperation.delete(deletionRange)], _edits => prevSelection);
211	
212			editor?.setSelections(prevSelection);
213		}
214	}
215	
216	class FormatOnSaveParticipant implements ITextFileSaveParticipant {
217	
218		constructor(
219			@IConfigurationService private readonly configurationService: IConfigurationService,
220			@ICodeEditorService private readonly codeEditorService: ICodeEditorService,
221			@IInstantiationService private readonly instantiationService: IInstantiationService,
222		) {
223			// Nothing
224		}
225	
226		async participate(model: ITextFileEditorModel, context: ITextFileSaveParticipantContext, progress: IProgress<IProgressStep>, token: CancellationToken): Promise<void> {
227			if (!model.textEditorModel) {
228				return;
229			}
230			if (context.reason === SaveReason.AUTO) {
231				return undefined;
232			}
233	
234			const textEditorModel = model.textEditorModel;
235			const overrides = { overrideIdentifier: textEditorModel.getLanguageId(), resource: textEditorModel.uri };
236	
237			const nestedProgress = new Progress<{ displayName?: string; extensionId?: ExtensionIdentifier }>(provider => {
238				progress.report({
239					message: localize(
240						{ key: 'formatting2', comment: ['[configure]({1}) is a link. Only translate `configure`. Do not change brackets and parentheses or {1}'] },
241						"Running '{0}' Formatter ([configure]({1})).",
242						provider.displayName || provider.extensionId && provider.extensionId.value || '???',
243						createCommandUri('workbench.action.openSettings', 'editor.formatOnSave').toString(),
244					)
245				});
246			});
247	
248			const enabled = this.configurationService.getValue<boolean>('editor.formatOnSave', overrides);
249			if (!enabled) {
250				return undefined;
251			}
